using System;using System.IO;using System.Diagnostics;using System.Linq;using System.Collections.Generic;using System.Threading;using System.IO.MemoryMappedFiles;using System.Security.Principal;using System.Security.AccessControl;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using ThinkPadModesV3;
internal sealed class OcctRunIdentity {public int Parent,Pid,Session,Watts=15;public long StartTicks;public string Exe,Hash,ParentHash,Directory,Journal;}
internal static class OcctExternalGuard {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16*1024*1024};static volatile bool cancel,beat;static readonly string Root=Path.Combine(Paths.Data,"ExternalBurn");static string Image{get{return typeof(OcctExternalGuard).Assembly.Location;}}static long Tick{get{return CoolingPaths.Tick;}}static bool Admin{get{return new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator);}}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct Entry{public uint Size,Usage,Pid;public UIntPtr Heap;public uint Module,Threads,Parent;public int Priority;public uint Flags;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=260)]public string Name;}
 [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr CreateToolhelp32Snapshot(uint flags,uint pid);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool Process32First(IntPtr h,ref Entry e);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool Process32Next(IntPtr h,ref Entry e);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);
 static void Save(string file,object data){Atomic.Write(file,Json.Serialize(data));}
 static Process Target(OcctRunIdentity id){var p=Process.GetProcessById(id.Pid);if(p.HasExited||p.ProcessName!="OCCTGUI"||p.SessionId!=id.Session||p.StartTime.ToUniversalTime().Ticks!=id.StartTicks){p.Dispose();throw new IOException("L’identité OCCT a changé");}return p;}
 static List<int> Descendants(int root){var rows=new List<Tuple<int,int>>();IntPtr snap=CreateToolhelp32Snapshot(2,0);if(snap==new IntPtr(-1))throw new IOException("Inventaire processus indisponible");try{var e=new Entry{Size=(uint)Marshal.SizeOf(typeof(Entry))};if(Process32First(snap,ref e))do{rows.Add(Tuple.Create((int)e.Pid,(int)e.Parent));}while(Process32Next(snap,ref e));}finally{CloseHandle(snap);}var ids=new List<int>{root};for(int n=0;n<ids.Count;n++)foreach(var row in rows.Where(x=>x.Item2==ids[n]))if(!ids.Contains(row.Item1))ids.Add(row.Item1);return ids;}
 static double CpuTime(OcctRunIdentity id){using(var root=Target(id)){}double total=0;foreach(int pid in Descendants(id.Pid))try{using(var p=Process.GetProcessById(pid)){if(p.SessionId==id.Session&&p.StartTime.ToUniversalTime().Ticks>=id.StartTicks)total+=p.TotalProcessorTime.TotalMilliseconds;}}catch(ArgumentException){}return total;}
 static void StopOcct(OcctRunIdentity id){try{using(var root=Target(id)){}var ids=Descendants(id.Pid);ids.Reverse();foreach(int pid in ids)try{using(var p=Process.GetProcessById(pid)){if(!p.HasExited&&p.SessionId==id.Session&&p.StartTime.ToUniversalTime().Ticks>=id.StartTicks){p.Kill();p.WaitForExit(5000);}}}catch(ArgumentException){}}catch(ArgumentException){}}
 static void Auto(){var r=CoolingClient.Send("set","Auto");if(!r.Ok)throw new IOException(r.Error);}
 static void Protect(string path){Directory.CreateDirectory(path);var acl=new DirectorySecurity();acl.SetAccessRuleProtection(true,false);acl.SetOwner(new SecurityIdentifier("S-1-5-32-544"));foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(Paths.Info().OwnerSid),FileSystemRights.ReadAndExecute,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.SetAccessControl(path,acl);}
 static int Watch(string folder){folder=Path.GetFullPath(folder);if(!folder.StartsWith(Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return 77;var id=Json.Deserialize<OcctRunIdentity>(File.ReadAllText(Path.Combine(folder,"identity.json")));using(var parent=Process.GetProcessById(id.Parent)){if(Digest.Of(parent.MainModule.FileName)!=id.ParentHash||id.ParentHash!=Digest.Of(Image)||id.Directory!=folder)return 77;using(var initial=Target(id)){if(Digest.Of(initial.MainModule.FileName)!=id.Hash)throw new IOException("OCCT executable digest differs");}var rows=new List<object>();string reason=null;bool complete=false;long begin=Tick,lastLoad=0,lastRow=0,active=0,readyAt=0,belowSince=-1;double previousCpu=CpuTime(id),ratio=0;try{using(var mm=MemoryMappedFile.CreateFromFile(Path.Combine(folder,"watch.bin"),FileMode.Open,null,128))using(var v=mm.CreateViewAccessor())using(var cpu=new CalibrationCpu())using(var gpu=new NvmlTelemetry()){
  while(true){double c=cpu.Temperature();var g=gpu.Read()["GpuTemperature"];if(g.Status!="valid"||!g.Value.HasValue)throw new IOException("GPU NVML indisponible");ZeroDbCalibrator.Limits(c,g.Value.Value);if(!WindowsPower.OnMains())throw new IOException("Secteur débranché");v.Write(8,Tick);v.Write(48,c);v.Write(56,g.Value.Value);if(parent.HasExited||Tick-v.ReadInt64(0)>2500)throw new IOException("Gardien principal absent");if(v.ReadInt64(16)!=0)throw new OperationCanceledException("Annulation/erreur du contrôleur");if(Tick-begin>480000)throw new IOException("Durée totale maximale dépassée");bool ready=v.ReadInt64(96)==1;if(ready&&readyAt==0)readyAt=Tick;if(readyAt>0&&active==0&&Tick-readyAt>180000)throw new IOException("Aucune charge OCCT détectée en180s");
   if(Tick-lastLoad>=500){double current=CpuTime(id);if(lastLoad!=0)ratio=Math.Max(0,(current-previousCpu)/(Tick-lastLoad)/Environment.ProcessorCount);previousCpu=current;lastLoad=Tick;v.Write(80,ratio);if(!ready&&ratio>.25)throw new IOException("Charge OCCT lancée avant la fin de la préparation");if(ready&&ratio>.25&&active==0){active=Tick;v.Write(24,active);}if(active>0){if(ratio<.20){if(belowSince<0)belowSince=Tick;if(Tick-belowSince>3000)throw new IOException("Charge CPU OCCT interrompue avant180s");}else belowSince=-1;} }
   if(Tick-lastRow>=500){rows.Add(new{UTC=DateTime.UtcNow.ToString("o"),ElapsedMs=active==0?0:Tick-active,Cpu=c,Gpu=g.Value.Value,OcctCpuFraction=ratio});lastRow=Tick;}
   if(active>0&&Tick-active>=180000){complete=true;break;}Thread.Sleep(100);
  }
 }}catch(Exception e){reason=e.Message;}finally{try{StopOcct(id);}catch(Exception e){reason=(reason??"")+" ; arrêtOCCT: "+e.Message;complete=false;}try{Auto();var resume=CoolingClient.Send("resume-acquisition");if(!resume.Ok)throw new IOException(resume.Error);}catch(Exception e){reason=(reason??"")+" ; Auto: "+e.Message;complete=false;}if(parent.HasExited)try{new ZeroPowerLease(id.Journal,true);}catch(Exception e){reason=(reason??"")+" ; restaurationCPU: "+e.Message;complete=false;}Save(Path.Combine(folder,"watch-result.json"),new{UTC=DateTime.UtcNow.ToString("o"),Completed=complete,Error=reason,ElapsedMs=active==0?0:Tick-active,ForcedFanStop=false,Samples=rows});}return complete?0:1;}}
 static int? ChooseDelay(Dictionary<string,object> data){object value;if(data==null||!data.TryGetValue("Rows",out value)||!(value is System.Collections.IEnumerable))return null;var records=((System.Collections.IEnumerable)value).Cast<object>().OfType<Dictionary<string,object>>().ToArray();foreach(int delay in new[]{1,2,5,0}){var subset=records.Where(x=>Convert.ToInt32(x["DelayMs"])==delay).ToArray();if(subset.Length==12&&subset.Any(x=>Convert.ToInt32(((Dictionary<string,object>)x["Fan1"])["Rpm"])>0&&Convert.ToInt32(((Dictionary<string,object>)x["Fan2"])["Rpm"])>0)&&subset.All(x=>(bool)((Dictionary<string,object>)x["Fan1"])["Valid"]&&(bool)((Dictionary<string,object>)x["Fan2"])["Valid"]))return delay;}return null;}
 static int VerifyJson(){for(int test=0;test<6;test++){var rows=new List<object>();for(int n=0;n<(test==4?11:12);n++)rows.Add(new Dictionary<string,object>{{"DelayMs",1},{"Fan1",new Dictionary<string,object>{{"Valid",true},{"Rpm",test==2?0:2500}}},{"Fan2",new Dictionary<string,object>{{"Valid",test==1&&n==5?false:true},{"Rpm",test==2?0:2490}}}});var data=new Dictionary<string,object>();if(test!=3)data["Rows"]=test==5?(object)rows.ToArray():rows;var decoded=test==5?data:Json.Deserialize<Dictionary<string,object>>(Json.Serialize(data));int? result=ChooseDelay(decoded);bool expected=test==0||test==5;if((result==1)!=expected)return 1;}Console.WriteLine("RpmJsonIntegrationFixtures=6 PASS (ArrayList/array, invalid/zero/missing/incomplete)");return 0;}
 static int Run(int pid){using(var gate=new Mutex(false,@"Global\ThinkPadModes.Calibration")){bool held=false;try{try{held=gate.WaitOne(0);}catch(AbandonedMutexException){gate.ReleaseMutex();throw new IOException("Ancien test interrompu : contrôler les journaux avant reprise");}if(!held)throw new IOException("Un autre test est actif");return RunCore(pid);}finally{if(held)gate.ReleaseMutex();}}}
 static int RunCore(int pid){Console.CancelKeyPress+=(s,e)=>{e.Cancel=true;cancel=true;};LenovoOemTransport.Verify();if(!WindowsPower.OnMains())throw new IOException("Chargeur requis");string folder=Path.Combine(Root,Guid.NewGuid().ToString("N"));Protect(Root);Protect(folder);var id=new OcctRunIdentity{Parent=Process.GetCurrentProcess().Id,ParentHash=Digest.Of(Image),Pid=pid,Session=Process.GetCurrentProcess().SessionId,Directory=folder,Journal=Path.Combine(folder,"cpu-lease.json")};using(var occt=Process.GetProcessById(pid)){if(occt.ProcessName!="OCCTGUI"||occt.SessionId!=id.Session)throw new IOException("OCCTGUI attendu dans cette session");id.Exe=occt.MainModule.FileName;id.Hash=Digest.Of(id.Exe);id.StartTicks=occt.StartTime.ToUniversalTime().Ticks;}Save(Path.Combine(folder,"identity.json"),id);
  Process watcher=null;ZeroPowerLease lease=null;Thread heartbeat=null;MemoryMappedFile memory=null;MemoryMappedViewAccessor view=null;string error=null;var samples=new List<object>();var tachRows=new List<object>();bool completed=false,rpmPaused=false;int? tachDelay=null;try{Auto();lease=new ZeroPowerLease(id.Journal,false,15);using(var f=File.Create(Path.Combine(folder,"watch.bin")))f.SetLength(128);memory=MemoryMappedFile.CreateFromFile(Path.Combine(folder,"watch.bin"),FileMode.Open,null,128);view=memory.CreateViewAccessor();view.Write(0,Tick);beat=true;heartbeat=new Thread(()=>{while(beat){view.Write(0,Tick);Thread.Sleep(100);}}){IsBackground=true};heartbeat.Start();watcher=Process.Start(new ProcessStartInfo(Image,"--watch \""+folder+"\""){UseShellExecute=false,CreateNoWindow=true});Console.WriteLine("Préparation : Auto Lenovo,15W,Turbo BoostOFF. Ne pas encore lancerOCCT.");Save(Path.Combine(folder,"progress.json"),new{UTC=DateTime.UtcNow.ToString("o"),Stage="PreparingReadOnlyRpm",Watts=15});int probe=SettledRpmProbe.Main(new[]{"--read",Path.Combine(folder,"rpm-probe.json")});if(probe!=0)Console.WriteLine("Lecture RPM non qualifiée : cet essai reste uniquement enAuto, jamais0dB.");if(File.Exists(Path.Combine(folder,"rpm-probe.json")))tachDelay=ChooseDelay(Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(folder,"rpm-probe.json"))));if(tachDelay.HasValue){var pause=CoolingClient.Send("pause");if(!pause.Ok)throw new IOException(pause.Error);rpmPaused=true;Console.WriteLine("Adaptateur RPM en lecture seule actif, délai"+tachDelay.Value+"ms, validation sous charge enAuto.");}if(!lease.Verified)throw new IOException("LimitesCPU modifiées");if(watcher.HasExited)throw new IOException("Préparation interrompue par le gardien");view.Write(96,1L);Console.WriteLine("PRÊT : lancer le testCPU seul dansOCCT. Le gardien fermeraOCCT après180s de charge ou au seuil90CPU/80GPU.");long last=0;while(!watcher.HasExited){if(cancel)throw new OperationCanceledException();if(!lease.Verified)throw new IOException("RéglagesCPU modifiés extérieurement");if(Tick-view.ReadInt64(8)>2500)throw new IOException("Gardien externe silencieux");if(Tick-last>1000){double? watts=null;try{var s=PipeClient.Send("status");SensorValue w;if(s.Ok&&s.Snapshot.Sensors.TryGetValue("CpuWatts",out w)&&w.Status=="valid"&&w.Value.HasValue&&(DateTime.UtcNow-DateTime.Parse(w.AcquiredUtc).ToUniversalTime()).TotalMilliseconds<4500)watts=w.Value.Value;}catch{}object tach=null;if(tachDelay.HasValue){try{tach=SettledRpmProbe.Observe(tachDelay.Value);tachRows.Add(tach);}catch(Exception e){tachRows.Add(new{UTC=DateTime.UtcNow.ToString("o"),Error=e.Message});tachDelay=null;}}long start=view.ReadInt64(24);var row=new{UTC=DateTime.UtcNow.ToString("o"),Stage=start==0?"ReadyForOcctCpu":"Running",ElapsedMs=start==0?0:Tick-start,Cpu=view.ReadDouble(48),Gpu=view.ReadDouble(56),MeasuredWatts=watts,OcctCpuFraction=view.ReadDouble(80),ForcedFanStop=false,Watts=15,Rpm=tach};samples.Add(row);Save(Path.Combine(folder,"progress.json"),row);last=Tick;}Thread.Sleep(100);}var result=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(folder,"watch-result.json")));completed=(bool)result["Completed"];error=Convert.ToString(result["Error"]);
  }catch(Exception e){error=e.Message;}finally{if(view!=null)view.Write(16,1L);try{if(watcher!=null&&!watcher.HasExited){if(!watcher.WaitForExit(6000)){StopOcct(id);watcher.Kill();watcher.WaitForExit();}}else StopOcct(id);}catch(Exception e){error=(error??"")+" ; arrêt: "+e.Message;}try{if(rpmPaused){var resume=CoolingClient.Send("resume-acquisition");if(!resume.Ok)throw new IOException(resume.Error);}Auto();}catch(Exception e){error=(error??"")+" ; Auto: "+e.Message;}try{if(lease!=null)lease.Dispose();}catch(Exception e){error=(error??"")+" ; CPU: "+e.Message;}beat=false;if(heartbeat!=null)heartbeat.Join(1000);if(view!=null)view.Dispose();if(memory!=null)memory.Dispose();if(watcher!=null)watcher.Dispose();Save(Path.Combine(folder,"result.json"),new{UTC=DateTime.UtcNow.ToString("o"),Completed=completed&&String.IsNullOrEmpty(error),BurnCompleted=completed,Error=error,Watts=15,RpmObservations=tachRows,ZeroDbQualified=false,ForcedFanStop=false,CpuLeaseRestored=!File.Exists(id.Journal),Samples=samples});Console.WriteLine("Rapport : "+Path.Combine(folder,"result.json"));}return completed&&String.IsNullOrEmpty(error)?0:1;
 }
 static void LaunchTrace(object data){string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ThinkPadModes","OcctLauncher");Directory.CreateDirectory(dir);Save(Path.Combine(dir,"latest.json"),data);}
 public static int Main(string[] a){if(a.Length==0){var open=Process.GetProcessesByName("OCCTGUI").Where(x=>x.SessionId==Process.GetCurrentProcess().SessionId).ToArray();if(open.Length!=1){Console.WriteLine("Ouvrir une seule instance OCCT avant le gardien. Entrée pour fermer.");if(!Console.IsInputRedirected)Console.ReadLine();return 64;}a=new[]{"--attach",open[0].Id.ToString()};foreach(var p in open)p.Dispose();}bool launcher=a.Length==2&&a[0]=="--attach";if(a.Length==1&&a[0]=="--verify"){int code=ZeroDbCalibrator.Main(new[]{"--verify-guards"});return code==0?VerifyJson():code;}try{if(a.Length==2&&a[0]=="--watch")return Admin?Watch(a[1]):77;if(a.Length==2&&a[0]=="--run")return Admin?Run(Int32.Parse(a[1])):77;if(a.Length!=2||a[0]!="--attach")return 64;Console.WriteLine("GardienOCCT enAuto : plafond15W,tempCPU90/GPU80,180s. OCCT et ses processus de test seront arrêtés à la fin ou en cas de problème. Aucun arrêt forcé des ventilateurs.");LaunchTrace(new{UTC=DateTime.UtcNow.ToString("o"),Stage="WaitingForUAC"});var p=Process.Start(new ProcessStartInfo(Image,"--run "+Int32.Parse(a[1])){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Normal});LaunchTrace(new{UTC=DateTime.UtcNow.ToString("o"),Stage="ElevatedProcessStarted"});p.WaitForExit();LaunchTrace(new{UTC=DateTime.UtcNow.ToString("o"),Stage="Finished",ExitCode=p.ExitCode});Console.WriteLine("Terminé,code"+p.ExitCode+". Entrée pour fermer.");if(!Console.IsInputRedirected)Console.ReadLine();return p.ExitCode;}catch(Exception e){if(launcher){LaunchTrace(new{UTC=DateTime.UtcNow.ToString("o"),Stage="LaunchFailed",Error=e.Message});Console.WriteLine(e.Message);Console.WriteLine("Entrée pour fermer.");if(!Console.IsInputRedirected)Console.ReadLine();}else Console.WriteLine(e.Message);return 1;}}
